"""Join takes generated by several `dub.py gen` runs (each over its own time range) into one out_dir.

usage: DUB_LANG=pl python dub_merge.py <subs.srt> <out_dir> <part_dir>...
A part without manifest.json (a run stopped once the next part had taken over) is rebuilt from its
takes/NNN_K.wav files: sentence NNN of the run that started at the first sentence of that part.
Writes out_dir/manifest.json, sorted by time, with one entry per sentence.
"""
import glob
import json
import os
import sys

import dub


def part_manifest(subs, part):
    f = os.path.join(part, "manifest.json")
    if os.path.exists(f):
        return json.load(open(f, encoding="utf-8"))
    sents = dub.sentences(dub.srt(subs))
    out = []
    for i, (s, e, text) in enumerate(sents):   # a stopped part always started at time 0 here
        takes = sorted(glob.glob(os.path.join(part, "takes", "%03d_*.wav" % i)))
        if not takes:
            break
        out.append({"start": s, "end": e, "text": text, "say": dub.speakable(text, os.environ.get("DUB_LANG", "pl")), "takes": takes})
    return out


def main():
    subs, out, parts = sys.argv[1], sys.argv[2], sys.argv[3:]
    dub.load_say(out, os.environ.get("DUB_LANG", "pl"))
    by_start = {}
    for p in parts:
        for m in part_manifest(subs, p):
            by_start.setdefault(round(m["start"], 2), m)
    man = [by_start[k] for k in sorted(by_start)]
    want = [round(s, 2) for s, e, t in dub.sentences(dub.srt(subs))]
    missing = [w for w in want if w not in by_start]
    os.makedirs(out, exist_ok=True)
    json.dump(man, open(os.path.join(out, "manifest.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print("%d sentences, %d missing %s" % (len(man), len(missing), missing[:10]))


if __name__ == "__main__":
    main()
